 529				\hat{M}^{(\mathrm{Point},Z),z}_{b} \,
 530				\hat{M}^{(\mathrm{Point},X),x}_{a}
 531				\Big)_{\mathsf{B}\mathsf{A}''}\,.
 532			\end{gather}
 533		\end{enumerate}
